@font-face {
  font-family: 'IBM Plex Sans';
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2-variations'),
       url(data:font/woff2;base64,) format('woff2');
}
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2-variations'),
       url(data:font/woff2;base64,) format('woff2');
}

:root {
  --cc-orange: #EA633F;
  --cc-yellow: #E8EB74;
  --cc-cyan: #88E8F0;
  --cc-cream-light: #F5F2E8;
  --cc-cream: #F5F2E8;
  --cc-cream-deep: #E8E4D4;
  --cc-cream-soft: #F5F2E8;
  --cc-cream-dark: #E8E4D4;
  --cc-light-gray: #F5F5F5;
  --cc-light-gray-2: #ECECEC;
  --cc-rule-dark: rgba(255,255,255,0.10);
  --cc-black: #121212;
  --cc-white: #FFFFFF;
  --cc-light-gray: #F5F5F5;
  --cc-warm-gray: #E8E8E8;
  --cc-rule: #D6D2C5;
  --cc-rule-soft: #E8E4D4;
  --cc-mid-gray: #666666;
  --cc-ink-soft: #4A4A4A;
  --cc-ink-muted: #888080;
  --font-display: 'IBM Plex Sans', 'Helvetica Neue', Arial, sans-serif;
  --font-body: 'Inter', Arial, sans-serif;
  --font-mono: 'IBM Plex Mono', 'SF Mono', Menlo, Monaco, Consolas, monospace;
  --accent: var(--cc-orange);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--cc-white);
  color: var(--cc-black);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--cc-black); text-decoration: none; }
em { font-style: italic; }
strong { font-weight: 600; }
code {
  font-family: var(--font-mono);
  font-size: 12.5px;
  background: var(--cc-light-gray);
  padding: 1px 6px;
  border-radius: 2px;
  color: var(--cc-ink-soft);
  border: 1px solid var(--cc-warm-gray);
}

/* ============================================================
   COVER PAGE
   ============================================================ */
.cover {
  background: var(--cc-black);
  color: var(--cc-white);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 56px 72px 40px;
  position: relative;
}
.cover-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 80px;
}
.cover-top .brand {
  display: flex;
  align-items: center;
  gap: 14px;
}
.cover-top .brand img { height: 28px; }
.cover-top .brand-label {
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.55);
}
.cover-top .status {
  display: flex;
  gap: 10px;
  align-items: center;
}

.cover-body {
  flex: 1;
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 64px;
  align-items: start;
}

.cover-headline-block {
  max-width: 720px;
}
.cover-pid {
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--cc-orange);
  margin-bottom: 24px;
}
.cover h1 {
  font-family: var(--font-display);
  font-weight: 300;
  font-size: 88px;
  line-height: 0.98;
  letter-spacing: -0.025em;
  color: var(--cc-white);
  margin: 0 0 32px;
}
.cover h1 .accent-period { color: var(--cc-orange); }
.cover-lede {
  font-family: var(--font-display);
  font-weight: 300;
  font-size: 22px;
  line-height: 1.4;
  color: rgba(255,255,255,0.80);
  max-width: 580px;
  margin: 0 0 40px;
}

.cover-meta {
  background: rgba(255,255,255,0.05);
  padding: 24px 28px;
  border-left: 3px solid var(--cc-orange);
}
.cover-meta dl {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 10px 20px;
  margin: 0;
}
.cover-meta dt {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 10px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.55);
}
.cover-meta dd {
  margin: 0;
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--cc-white);
}

.cover-toc {
  background: var(--cc-white);
  padding: 32px;
  border: 1px solid var(--cc-rule);
}
.cover-toc-label {
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--cc-orange);
  margin-bottom: 4px;
}
.cover-toc-title {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 500;
  letter-spacing: -0.005em;
  margin: 0 0 20px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--cc-rule);
}
.cover-toc-item {
  display: grid;
  grid-template-columns: 36px 1fr auto;
  align-items: baseline;
  gap: 8px;
  padding: 12px 0;
  border-bottom: 1px solid var(--cc-rule-soft);
  text-decoration: none;
  color: var(--cc-black);
  transition: padding-left 0.15s ease;
}
.cover-toc-item:last-child { border-bottom: none; }
.cover-toc-item:hover {
  padding-left: 6px;
}
.cover-toc-item:hover .toc-arrow { color: var(--cc-orange); }
.cover-toc-item .toc-num {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 500;
  color: var(--cc-orange);
  letter-spacing: -0.01em;
}
.cover-toc-item .toc-label {
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.005em;
}
.cover-toc-item .toc-meta {
  font-family: var(--font-display);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--cc-ink-muted);
}
.cover-toc-item .toc-arrow {
  font-family: var(--font-display);
  color: var(--cc-ink-muted);
  font-size: 16px;
  font-weight: 300;
  transition: color 0.15s ease;
}

.cover-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 24px;
  margin-top: 56px;
  border-top: 1px solid rgba(255,255,255,0.15);
}
.cover-footer .left {
  display: flex;
  align-items: center;
  gap: 16px;
}
.cover-footer img.cc-icon { height: 28px; }
.cover-footer .meta-text,
.cover-footer .page-num {
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.55);
}

/* ============================================================
   CONTENT PAGES (with sidebar)
   ============================================================ */
.layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  min-height: 100vh;
}

.sidebar {
  background: var(--cc-black);
  color: var(--cc-white);
  border-right: 1px solid rgba(255,255,255,0.08);
  padding: 36px 24px 28px;
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
  font-family: var(--font-body);
  display: flex;
  flex-direction: column;
}

.sb-brand-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid rgba(255,255,255,0.10);
}
.sb-brand-row img { height: 22px; }
.sb-brand-row .sb-back {
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.55);
}
.sb-brand-row .sb-back:hover { color: var(--cc-orange); }

.sb-project-id {
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--cc-orange);
  margin-bottom: 8px;
}
.sb-project-name {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 17px;
  color: var(--cc-white);
  line-height: 1.25;
  margin-bottom: 16px;
  letter-spacing: -0.005em;
}
.sb-status {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 24px;
  padding-bottom: 24px;
  border-bottom: 1px solid rgba(255,255,255,0.10);
}
.sb-stage {
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.55);
}

.sb-section-label {
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.45);
  margin: 8px 0 12px;
}

nav.sb-nav { margin-bottom: 28px; }
.sb-link {
  display: grid;
  grid-template-columns: 28px 1fr 16px;
  grid-template-areas:
    "num label arrow"
    "num meta  arrow";
  gap: 0 12px;
  padding: 10px 12px 10px 14px;
  margin: 0 -14px;
  border-left: 2px solid transparent;
  text-decoration: none;
  transition: padding-left 0.15s ease, background 0.15s ease;
}
.sb-link:hover {
  background: rgba(255,255,255,0.04);
}
.sb-link:hover .sb-link-arrow { color: var(--cc-orange); }
.sb-link:hover .sb-link-label { color: var(--cc-white); }
.sb-link.active {
  border-left-color: var(--cc-orange);
}
.sb-link.active .sb-link-label { color: var(--cc-white); }
.sb-link.active .sb-link-arrow { color: var(--cc-orange); }

.sb-link-num {
  grid-area: num;
  align-self: baseline;
  padding-top: 2px;
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 500;
  color: var(--cc-orange);
  letter-spacing: -0.01em;
}
.sb-link-label {
  grid-area: label;
  align-self: end;
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 500;
  color: rgba(255,255,255,0.82);
  letter-spacing: -0.005em;
  line-height: 1.25;
}
.sb-link-meta {
  grid-area: meta;
  align-self: start;
  font-family: var(--font-display);
  font-size: 9.5px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.42);
  margin-top: 3px;
  line-height: 1.2;
}
.sb-link-arrow {
  grid-area: arrow;
  align-self: center;
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 400;
  color: rgba(255,255,255,0.25);
  text-align: right;
}
.sb-link.muted .sb-link-label { color: rgba(255,255,255,0.55); font-style: italic; }
.sb-link.muted:hover .sb-link-label { color: rgba(255,255,255,0.82); font-style: italic; }

.sb-link-ext {
  display: block;
  padding: 5px 0;
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: rgba(255,255,255,0.65);
  line-height: 1.3;
  letter-spacing: -0.01em;
}
.sb-link-ext:hover { color: var(--cc-orange); }
.sb-link-ext .ext-arrow { color: rgba(255,255,255,0.35); margin-left: 4px; }

.sb-footer-meta {
  margin-top: auto;
  padding-top: 20px;
  border-top: 1px solid rgba(255,255,255,0.10);
}
.sb-footer-meta .row {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 11px;
  color: rgba(255,255,255,0.65);
  margin-bottom: 4px;
  letter-spacing: -0.01em;
}
.sb-footer-meta .row strong {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.45);
}

/* Main content */
.main {
  background: var(--cc-white);
  padding: 56px 72px 0;
  max-width: 1440px;
  width: 100%;
}

.main-inner {
  min-height: calc(100vh - 100px);
  display: flex;
  flex-direction: column;
}
.main-content { flex: 1; padding-bottom: 56px; }

.main-section-label {
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--cc-orange);
  margin-bottom: 12px;
}

.main h1 {
  font-family: var(--font-display);
  font-size: 44px;
  font-weight: 400;
  line-height: 1.08;
  letter-spacing: -0.015em;
  margin: 0 0 16px;
  color: var(--cc-black);
}

.main h2 {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 500;
  line-height: 1.25;
  margin: 40px 0 14px;
  color: var(--cc-black);
  letter-spacing: -0.005em;
}
.main h2:first-of-type { margin-top: 32px; }

.main h3 {
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 500;
  margin: 28px 0 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--cc-ink-muted);
}

.main p {
  margin: 0 0 16px;
  color: var(--cc-black);
  max-width: 680px;
  font-size: 16px;
  line-height: 1.6;
}

.lede {
  font-family: var(--font-display);
  font-weight: 300;
  font-size: 24px;
  line-height: 1.35;
  color: var(--cc-black);
  margin: 16px 0 32px;
  max-width: 720px;
  letter-spacing: -0.01em;
}

/* Page metadata */
dl.metadata {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 8px 24px;
  margin: 12px 0 32px;
  padding: 18px 22px;
  background: var(--cc-light-gray);
  border-left: 3px solid var(--cc-orange);
}
dl.metadata dt {
  font-family: var(--font-display);
  font-weight: 500;
  color: var(--cc-ink-soft);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
dl.metadata dd {
  font-family: var(--font-body);
  margin: 0;
  font-size: 14px;
  color: var(--cc-black);
}
dl.metadata dd code { font-size: 12.5px; }

/* Working notes */
.note {
  background: var(--cc-light-gray);
  border-left: 3px solid var(--cc-orange);
  padding: 18px 22px;
  margin: 24px 0 28px;
  font-size: 14.5px;
  line-height: 1.6;
  color: var(--cc-ink-soft);
  max-width: 720px;
}
.note .note-label {
  font-family: var(--font-display);
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--cc-orange);
  font-weight: 600;
  margin-bottom: 8px;
}
.note a { color: var(--cc-black); text-decoration: underline; text-decoration-color: var(--cc-rule); }
.note a:hover { text-decoration-color: var(--cc-orange); }

/* Tags */
.tag {
  display: inline-block;
  padding: 3px 10px;
  font-family: var(--font-display);
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--cc-ink-soft);
  background: var(--cc-white);
  border: 1px solid var(--cc-rule);
  border-radius: 20px;
  white-space: nowrap;
  line-height: 1.4;
}
.tag.accent { color: var(--cc-orange); border-color: var(--cc-orange); background: rgba(234, 99, 63, 0.08); }
.tag.dark { background: var(--cc-black); color: var(--cc-white); border-color: var(--cc-black); }
.tag.muted { color: var(--cc-ink-muted); border-color: var(--cc-warm-gray); background: var(--cc-light-gray); }
.tag.solid-accent { background: var(--cc-orange); color: var(--cc-black); border-color: var(--cc-orange); }

/* Snapshot grid */
.snapshot-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin: 16px 0 32px;
}
.snap {
  background: var(--cc-light-gray);
  padding: 20px 22px;
  border-top: 2px solid var(--cc-orange);
}
.snap-num {
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 300;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--cc-black);
}
.snap-label {
  font-family: var(--font-display);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--cc-ink-muted);
  margin-top: 10px;
  font-weight: 500;
}

/* Section list */
.section-list { margin: 16px 0 32px; }
.sec-item {
  display: grid;
  grid-template-columns: 48px 1fr auto;
  align-items: center;
  gap: 20px;
  padding: 20px 24px;
  background: var(--cc-light-gray);
  border-bottom: 1px solid var(--cc-warm-gray);
  text-decoration: none;
  color: var(--cc-black);
  transition: background 0.15s ease;
}
.sec-item:hover {
  background: var(--cc-light-gray-2);
}
.sec-item:hover .sec-arrow { color: var(--cc-orange); }
.sec-item .sec-num {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 500;
  color: var(--cc-orange);
  letter-spacing: -0.01em;
}
.sec-item .sec-name {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 500;
  color: var(--cc-black);
  margin-bottom: 3px;
  letter-spacing: -0.005em;
}
.sec-item .sec-desc {
  font-family: var(--font-body);
  font-size: 13.5px;
  color: var(--cc-ink-soft);
  line-height: 1.5;
}
.sec-item .sec-arrow {
  font-family: var(--font-display);
  font-size: 16px;
  color: var(--cc-ink-muted);
  font-weight: 300;
}

/* Activity / decision log */
dl.activity { margin: 16px 0 24px; font-size: 14.5px; }
dl.activity dt {
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--cc-ink-muted);
  margin-bottom: 8px;
}
dl.activity dd {
  margin: 0 0 20px;
  color: var(--cc-black);
  padding-bottom: 20px;
  border-bottom: 1px solid var(--cc-rule-soft);
  line-height: 1.6;
  max-width: 720px;
}
dl.activity dd:last-child { border-bottom: none; }

/* Numbered list */
ol.numbered {
  margin: 16px 0 24px;
  padding: 0;
  counter-reset: nlist;
  list-style: none;
  max-width: 720px;
}
ol.numbered li {
  counter-increment: nlist;
  padding: 14px 0 14px 48px;
  position: relative;
  border-bottom: 1px solid var(--cc-rule-soft);
  color: var(--cc-black);
  font-size: 15.5px;
  line-height: 1.55;
}
ol.numbered li:last-child { border-bottom: none; }
ol.numbered li::before {
  content: counter(nlist, decimal-leading-zero);
  position: absolute;
  left: 0;
  top: 16px;
  font-family: var(--font-display);
  font-size: 16px;
  color: var(--cc-orange);
  letter-spacing: -0.02em;
  font-weight: 500;
}
ol.numbered li strong { color: var(--cc-black); font-weight: 600; }

/* Ask list */
ul.ask-list { list-style: none; margin: 16px 0 24px; padding: 0; max-width: 720px; }
ul.ask-list li {
  padding: 10px 0;
  font-size: 15px;
  color: var(--cc-black);
  line-height: 1.55;
  display: flex;
  align-items: baseline;
}
ul.ask-list li .tag { margin-right: 14px; flex-shrink: 0; }

/* Sample list */
ul.sample-list { list-style: none; margin: 16px 0; padding: 0; max-width: 720px; }
ul.sample-list li {
  display: grid;
  grid-template-columns: 40px 1fr;
  gap: 16px;
  padding: 12px 0;
  border-bottom: 1px solid var(--cc-rule-soft);
  align-items: baseline;
}
ul.sample-list li:last-child { border-bottom: none; }
ul.sample-list .slot {
  font-family: var(--font-display);
  font-size: 13px;
  color: var(--cc-orange);
  font-weight: 500;
  letter-spacing: -0.01em;
}
ul.sample-list .slot-desc { font-size: 14.5px; color: var(--cc-black); line-height: 1.55; }
ul.sample-list .slot-desc em { color: var(--cc-ink-muted); font-style: normal; font-size: 13.5px; }

/* Reference link blocks */
.ref-link {
  display: block;
  padding: 22px 24px;
  background: var(--cc-light-gray);
  border-left: 3px solid var(--cc-warm-gray);
  margin-bottom: 12px;
  transition: border-color 0.15s ease;
  max-width: 720px;
}
.ref-link[href]:hover { border-left-color: var(--cc-orange); }
.ref-link .ref-label {
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--cc-orange);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
