/* Page footer (per CC spec: section name left + page num right) */
.page-footer-strip {
  margin-top: auto;
  padding: 16px 0 20px;
  border-top: 1px solid var(--cc-rule);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
