.page-footer-strip .pn-prev { flex: 1; text-align: left; }
.page-footer-strip .pn-section { flex: 1; text-align: center; }
.page-footer-strip .pn-next { flex: 1; text-align: right; }

/* Schema preview */
.schema-grid {
