  padding: 18px 20px;
}
.schema-cell .sch-label {
  font-family: var(--font-display);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--cc-orange);
  margin-bottom: 10px;
  font-weight: 500;
}
.schema-cell .sch-desc {
  font-family: var(--font-body);
  font-size: 13.5px;
  color: var(--cc-ink-soft);
  line-height: 1.55;
}

/* Empty state */
.empty-state {
  padding: 40px;
  background: var(--cc-light-gray);
  border: 1px dashed var(--cc-warm-gray);
  text-align: center;
  margin: 20px 0 28px;
  max-width: 720px;
}
.empty-state .es-title {
  font-family: var(--font-display);
  font-size: 17px;
  font-weight: 500;
  color: var(--cc-ink-soft);
  margin-bottom: 8px;
  letter-spacing: -0.005em;
}
.empty-state .es-desc {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--cc-ink-muted);
}

/* ============================================================
   WIREFRAMES
   ============================================================ */
.wireframe-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin: 20px 0 0;
}
.wf-col-label {
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--cc-ink-muted);
  margin-bottom: 4px;
}
.wf-col-url {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--cc-ink-soft);
  margin-bottom: 14px;
  word-break: break-all;
  letter-spacing: -0.01em;
}
.wf {
  border: 1px solid var(--cc-rule);
  background: var(--cc-white);
}
.wf-block {
  position: relative;
  padding: 12px 14px 18px;
  border-bottom: 1px solid var(--cc-rule-soft);
}
.wf-block:last-child { border-bottom: none; }
.wf-block.dark { background: var(--cc-black); color: var(--cc-white); }
.wf-block.slim { padding: 8px 14px 10px; }
.wf-label {
  font-family: var(--font-display);
  font-size: 6.5px;
  letter-spacing: 0.2em;
  color: #999;
  text-transform: uppercase;
  margin-top: 8px;
  font-weight: 500;
}
.wf-block.dark .wf-label { color: rgba(255,255,255,0.55); }
.wf-anno-dot {
  position: absolute;
  top: 8px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--cc-orange);
  color: #FFFFFF;
  font-family: var(--font-display);
  font-size: 9px;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
}
.wf-anno-dot.right { right: 10px; }
.wf-anno-dot.right-2 { right: 32px; }

.wf-hero { display: flex; gap: 10px; }
.wf-hero-content { flex: 1; min-width: 0; }
.wf-hero-photo {
  width: 36%;
  background: #2A2A2A;
  position: relative;
  min-height: 82px;
}
.wf-hero-photo.light { background: var(--cc-light-gray); }
.wf-hero-photo::after {
  content: '';
  position: absolute;
  top: 12px; left: 50%;
  transform: translateX(-50%);
  width: 14px; height: 14px;
  background: var(--cc-orange);
  border-radius: 50%;
  opacity: 0.85;
}
.wf-hero-photo.light::after { opacity: 0.55; }

.wf-name { width: 55%; height: 5px; background: #FFFFFF; margin-bottom: 6px; }
.wf-name.dark { background: var(--cc-black); height: 6px; }
.wf-line { width: 100%; height: 2.2px; background: rgba(255,255,255,0.28); margin-bottom: 3px; }
.wf-line.short { width: 70%; }
.wf-line.shorter { width: 40%; }
.wf-line.dark { background: rgba(0,0,0,0.18); }
.wf-mini-label { width: 30%; height: 3.5px; background: #BBB; margin-bottom: 6px; }

.wf-ctas { margin-top: 8px; display: flex; gap: 4px; flex-wrap: wrap; }
.wf-cta {
  display: inline-block;
  padding: 3px 6px;
  border: 1px solid #FFFFFF;
  font-family: var(--font-display);
  font-size: 5.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 500;
}
.wf-cta.solid { background: var(--cc-orange); border-color: var(--cc-orange); color: var(--cc-black); }
.wf-cta.outline-dark { border-color: var(--cc-black); color: var(--cc-black); }
.wf-cta.centered { display: block; text-align: center; max-width: 60%; margin: 0 auto; padding: 5px 7px; }

.wf-two-col { display: grid; grid-template-columns: 1fr 1.5fr; gap: 10px; }
.wf-wall { display: flex; flex-wrap: wrap; gap: 2px; }
.wf-wall .pill { display: inline-block; height: 3.5px; background: #DDD7C7; }
.wf-wall.dense .pill { background: #C9C2B0; }

.wf-pills.curated { display: flex; gap: 4px; flex-wrap: wrap; }
.wf-pills.curated span { height: 8px; background: var(--cc-light-gray); border-radius: 4px; display: inline-block; }

.wf-stats { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 4px; margin: 6px 0; }
.wf-stat { background: rgba(0,0,0,0.05); border-left: 2px solid var(--cc-orange); height: 22px; }

.wf-articles { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.wf-article { background: var(--cc-light-gray); height: 32px; }

.wf-case-studies-row { display: flex; gap: 8px; }
.wf-cs-image { width: 30%; background: var(--cc-light-gray); height: 44px; }
.wf-cs-content { flex: 1; min-width: 0; }
.wf-cs-logos { margin-top: 8px; display: flex; gap: 4px; }
.wf-cs-logo { width: 22px; height: 9px; background: rgba(0,0,0,0.12); }
.wf-cs-logo.dark { background: rgba(255,255,255,0.22); }

.wf-cs-cards { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 4px; }
.wf-cs-card { background: var(--cc-light-gray); height: 34px; }

.wf-quote { background: rgba(0,0,0,0.03); border-left: 2px solid var(--cc-orange); padding: 6px 8px; }

.wf-off-hours { display: flex; gap: 8px; align-items: center; }
.wf-off-image { width: 40%; height: 36px; background: var(--cc-light-gray); }
.wf-off-image::after {
  content: ''; display: block;
  width: 14px; height: 14px;
  background: var(--cc-orange);
  border-radius: 50%;
  margin: 11px auto;
  opacity: 0.55;
}

.wf-nav-row { display: flex; align-items: center; gap: 8px; }
.wf-nav-brand { width: 28%; height: 5px; background: var(--cc-black); }
.wf-nav-links { flex: 1; display: flex; gap: 3px; }
.wf-nav-links span { width: 14px; height: 3px; background: #BBB; }
.wf-nav-cta {
  font-family: var(--font-display);
  font-size: 5.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--cc-orange);
  color: #FFFFFF;
  padding: 2px 6px;
  font-weight: 500;
}

.wf-annotations {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px 36px;
  margin-top: 36px;
  padding-top: 32px;
  border-top: 1px solid var(--cc-rule);
}
.wf-anno { display: grid; grid-template-columns: 32px 1fr; gap: 14px; align-items: start; }
.wf-anno-num {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--cc-orange);
  color: #FFFFFF;
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
}
.wf-anno h4 {
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 500;
  margin: 2px 0 6px;
  letter-spacing: -0.005em;
}
.wf-anno p {
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.55;
  color: var(--cc-ink-soft);
  margin: 0;
  max-width: none;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1100px) {
  .cover { padding: 40px 32px 32px; }
  .cover h1 { font-size: 56px; }
  .cover-body { grid-template-columns: 1fr; gap: 40px; }
  .cover-top { margin-bottom: 40px; }
}

@media (max-width: 1000px) {
  .layout { grid-template-columns: 1fr; }
  .sidebar { position: relative; height: auto; }
  .main { padding: 40px 32px; }
