  .snapshot-grid { grid-template-columns: repeat(2, 1fr); }
  .wireframe-grid { grid-template-columns: 1fr; }
  .wf-annotations { grid-template-columns: 1fr; }
  .schema-grid { grid-template-columns: 1fr; }
  .cover-meta dl { grid-template-columns: 1fr; gap: 2px 0; }
