    max-width: 1080px;
  }
  .summary-panel-label {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 600;
    margin-bottom: 4px;
  }
  .summary-panel h2.sum-h {
    font-family: var(--font-display);
    font-size: 22px;
    font-weight: 500;
    margin: 0 0 18px;
    color: var(--cc-black);
    letter-spacing: -0.005em;
  }
  .summary-panel h3.sum-h {
    font-family: var(--font-display);
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--cc-ink-soft);
    margin: 24px 0 12px;
  }
  .summary-panel h3.sum-h:first-of-type { margin-top: 0; }

  /* Two-column layout inside summary panel */
  .sum-cols {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 32px;
    margin-bottom: 20px;
  }
  .sum-cols ol {
    margin: 0;
    padding-left: 22px;
    font-size: 14px;
    line-height: 1.55;
    color: var(--cc-black);
  }
  .sum-cols ol li { margin-bottom: 8px; }
  .sum-cols ol li::marker {
    font-family: var(--font-display);
    color: var(--cc-orange);
    font-weight: 500;
  }

  .sum-tension {
    background: var(--cc-white);
    padding: 12px 14px;
    margin-bottom: 10px;
    border: 1px solid var(--cc-warm-gray);
    font-size: 14px;
    line-height: 1.5;
  }
  .sum-tension strong { color: var(--cc-black); }
  .sum-tension .resolved {
    display: block;
    margin-top: 6px;
    color: var(--cc-ink-soft);
    font-size: 13.5px;
  }
  .sum-tension .resolved::before {
    content: '→ ';
    color: var(--cc-orange);
    font-weight: 600;
  }

  .sum-voices-row {
    padding-top: 16px;
    margin-top: 4px;
    border-top: 1px solid var(--cc-warm-gray);
    font-family: var(--font-body);
    font-size: 13.5px;
    color: var(--cc-ink-soft);
  }
  .sum-voices-row strong {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--cc-ink-soft);
    font-weight: 500;
    margin-right: 8px;
  }

  /* Priority row (ideas page top 3) */
  .priority-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin: 0 0 24px;
  }
  .priority-item {
    display: grid;
    grid-template-columns: 36px 1fr;
    gap: 12px;
    align-items: center;
    padding: 14px 16px;
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    text-decoration: none;
    color: var(--cc-black);
    transition: border-color 0.15s ease;
  }
  .priority-item:hover { border-color: var(--cc-orange); }
  .priority-item .name {
    font-family: var(--font-display);
    font-size: 14px;
    font-weight: 500;
    color: var(--cc-black);
    letter-spacing: -0.005em;
    line-height: 1.25;
  }
  .priority-item .why {
    font-family: var(--font-body);
    font-size: 12.5px;
    color: var(--cc-ink-soft);
    margin-top: 3px;
    line-height: 1.4;
  }

  /* Themes grid */
  .theme-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin: 0 0 0;
  }
  .theme {
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    padding: 16px 18px;
  }
  .theme-name {
    font-family: var(--font-display);
    font-size: 13px;
    font-weight: 500;
    color: var(--cc-black);
    margin-bottom: 10px;
    letter-spacing: -0.005em;
  }
  .theme-ideas {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .theme-ideas a {
    display: grid;
    grid-template-columns: 32px 1fr;
    gap: 10px;
    align-items: center;
    font-family: var(--font-body);
    font-size: 13px;
    color: var(--cc-ink-soft);
    text-decoration: none;
    line-height: 1.35;
  }
  .theme-ideas a:hover { color: var(--cc-orange); }
  .theme-ideas .gp {
    font-family: var(--font-display);
    font-size: 10px;
    font-weight: 600;
    text-align: center;
    padding: 2px 4px;
    background: var(--cc-light-gray);
    color: var(--cc-black);
    border-radius: 2px;
  }
  .theme-ideas .gp.high { background: var(--cc-orange); color: var(--cc-black); }
  .theme-ideas .gp.mid { background: transparent; border: 1px solid var(--cc-black); }
  .theme-ideas .gp.low { background: var(--cc-light-gray); color: var(--cc-ink-muted); }
  .theme-ideas .gp.fail { background: transparent; color: var(--cc-ink-muted); border: 1px dashed var(--cc-ink-muted); text-decoration: line-through; }

  @media (max-width: 900px) {
    .sum-cols { grid-template-columns: 1fr; gap: 20px; }
    .priority-row { grid-template-columns: 1fr; }
    .theme-grid { grid-template-columns: 1fr; }
  }


  /* ============================================
     FILTER BAR — chip-based filtering
     ============================================ */
  .filter-bar {
    background: var(--cc-light-gray);
    padding: 16px 20px;
    margin: 20px 0 28px;
    border-left: 3px solid var(--cc-orange);
  }
  .filter-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    margin-bottom: 10px;
  }
  .filter-row:last-child { margin-bottom: 0; }
  .filter-row-label {
    font-family: var(--font-display);
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--cc-ink-soft);
    margin-right: 8px;
    min-width: 64px;
  }
  .filter-chip {
    font-family: var(--font-body);
    font-size: 12.5px;
    padding: 5px 11px;
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    color: var(--cc-black);
    cursor: pointer;
    transition: all 0.15s ease;
  }
  .filter-chip:hover { border-color: var(--cc-orange); }
  .filter-chip.active {
    background: var(--cc-orange);
    border-color: var(--cc-orange);
    color: var(--cc-black);
    font-weight: 600;
  }
  .filter-chip .filter-count {
    color: var(--cc-ink-soft);
    margin-left: 4px;
    font-size: 11px;
  }
  .filter-chip.active .filter-count { color: var(--cc-black); }

  /* ============================================
     ACCORDION IDEA CARDS — collapsed by default
     ============================================ */
  details.idea-card {
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    margin-bottom: 10px;
    transition: border-color 0.15s ease;
  }
  details.idea-card[open] {
    border-color: var(--cc-orange);
  }
  details.idea-card.idea-low { background: var(--cc-light-gray); opacity: 0.85; }
  details.idea-card.idea-low[open] { opacity: 1; }

  details.idea-card > summary {
    list-style: none;
    cursor: pointer;
    padding: 16px 20px;
    display: grid;
    grid-template-columns: 36px 1fr auto 220px 24px;
    gap: 14px;
    align-items: center;
  }
  details.idea-card > summary::-webkit-details-marker { display: none; }
  details.idea-card > summary::marker { display: none; }
  details.idea-card > summary:hover .idea-card-name { color: var(--cc-orange); }

  .idea-card-num {
    font-family: var(--font-display);
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.18em;
    color: var(--cc-ink-soft);
  }
  .idea-card-main { min-width: 0; }
  .idea-card-name {
    font-family: var(--font-display);
    font-size: 15.5px;
    font-weight: 600;
    color: var(--cc-black);
    margin-bottom: 4px;
    transition: color 0.15s ease;
    line-height: 1.3;
  }
  .idea-card-tagline {
    font-family: var(--font-body);
    font-size: 13px;
    color: var(--cc-ink-soft);
    line-height: 1.45;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .idea-card-grade-cell {
    display: flex;
    align-items: center;
    justify-content: center;
  }

  /* Mini criterion strip — 6 small chips */
  .mini-crit-strip {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 3px;
    align-items: center;
  }
  .mc {
    font-family: var(--font-display);
    font-size: 9px;
    font-weight: 600;
    padding: 4px 0;
    text-align: center;
    border-radius: 1px;
    line-height: 1;
  }
  .mc-A, .mc-Am { background: var(--cc-orange); color: var(--cc-black); }
  .mc-Bp, .mc-B { background: transparent; border: 1px solid var(--cc-black); color: var(--cc-black); }
  .mc-Bm, .mc-Cp, .mc-C { background: var(--cc-light-gray); color: var(--cc-ink-muted); border: 1px solid var(--cc-warm-gray); }
  .mc-D, .mc-F { background: transparent; color: var(--cc-ink-muted); border: 1px dashed var(--cc-ink-muted); text-decoration: line-through; }

  .idea-card-chevron {
    font-family: var(--font-display);
    font-size: 12px;
    color: var(--cc-ink-soft);
    text-align: center;
    transition: transform 0.2s ease;
  }
  details.idea-card[open] .idea-card-chevron {
    transform: rotate(90deg);
    color: var(--cc-orange);
  }

  details.idea-card > .idea-body {
    padding: 4px 20px 22px;
    border-top: 1px solid var(--cc-warm-gray);
    margin-top: 0;
  }
  .idea-card-source-row {
    font-family: var(--font-body);
    font-size: 12.5px;
    color: var(--cc-ink-soft);
    padding: 12px 0 4px;
    font-style: italic;
  }
  .idea-card-source-row strong { font-style: normal; font-family: var(--font-display); font-weight: 500; color: var(--cc-black); margin-right: 6px; }

  @media (max-width: 980px) {
    details.idea-card > summary {
      grid-template-columns: 36px 1fr auto;
      grid-template-rows: auto auto;
    }
    .mini-crit-strip { grid-column: 1 / -1; }
    .idea-card-chevron { display: none; }
    .in-page-toc { font-size: 9px; gap: 4px; }
  }

  /* ============================================
     COLLAPSIBLE SESSIONS (voices) + DECISIONS
     ============================================ */
  details.collapsible-section {
    margin: 24px 0;
    border-left: 3px solid var(--cc-warm-gray);
    padding-left: 18px;
    transition: border-color 0.15s ease;
  }
  details.collapsible-section[open] {
    border-left-color: var(--cc-orange);
  }
  details.collapsible-section > summary {
    list-style: none;
    cursor: pointer;
    padding: 0 0 6px;
    display: flex;
    align-items: baseline;
    gap: 12px;
  }
  details.collapsible-section > summary::-webkit-details-marker { display: none; }
  details.collapsible-section > summary::marker { display: none; }
  details.collapsible-section > summary h2,
  details.collapsible-section > summary h3 {
    margin: 0;
    display: inline;
  }
  .collapsible-meta {
    font-family: var(--font-body);
    font-size: 13px;
    color: var(--cc-ink-soft);
  }
  .collapsible-toggle {
    margin-left: auto;
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 600;
  }
  details.collapsible-section[open] .collapsible-toggle::before { content: 'Collapse ↑'; }
  details.collapsible-section:not([open]) .collapsible-toggle::before { content: 'Expand ↓'; }

  /* ============================================
     PAGE TOC — numbered list at top + scroll-triggered hamburger
     ============================================ */
  ol.page-toc {
    counter-reset: page-toc;
    list-style: none;
    margin: 24px 0 36px;
    padding: 0;
    border-top: 1px solid var(--cc-warm-gray);
    border-bottom: 1px solid var(--cc-warm-gray);
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 0;
  }
  ol.page-toc li {
    counter-increment: page-toc;
    padding: 12px 18px;
    border-right: 1px solid var(--cc-warm-gray);
    border-bottom: 1px solid var(--cc-warm-gray);
    transition: background 0.15s ease;
    position: relative;
  }
  ol.page-toc li:nth-last-child(-n+3) { border-bottom: none; }
  ol.page-toc li:last-child { border-right: none; }
  ol.page-toc li:hover { background: var(--cc-light-gray); }
  ol.page-toc li::before {
    content: counter(page-toc, decimal-leading-zero);
    font-family: var(--font-display);
    font-size: 10px;
    font-weight: 500;
    letter-spacing: 0.18em;
    color: var(--cc-orange);
    display: block;
    margin-bottom: 4px;
  }
  ol.page-toc a {
    color: var(--cc-black);
    text-decoration: none;
    font-family: var(--font-display);
    font-size: 13.5px;
    font-weight: 500;
    line-height: 1.3;
    display: block;
  }
  ol.page-toc a:hover { color: var(--cc-orange); }

  /* Hamburger button — fixed top-right, appears when ol.page-toc scrolls out */
  .toc-hamburger {
    position: fixed;
    top: 24px;
    right: 24px;
    z-index: 100;
    width: 44px;
    height: 44px;
    background: var(--cc-black);
    border: none;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 5px;
    padding: 0;
    opacity: 0;
    transform: translateY(-12px);
    pointer-events: none;
    transition: opacity 0.2s ease, transform 0.2s ease;
  }
  .toc-hamburger.visible {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
  }
  .toc-hamburger span {
    display: block;
    width: 18px;
    height: 2px;
    background: var(--cc-white);
    transition: all 0.2s ease;
  }
  .toc-hamburger:hover { background: var(--cc-orange); }
  .toc-hamburger:hover span { background: var(--cc-black); }
  .toc-hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
  .toc-hamburger.open span:nth-child(2) { opacity: 0; }
  .toc-hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

  /* Overlay dropdown — appears next to hamburger */
  .toc-overlay {
    position: fixed;
    top: 76px;
    right: 24px;
    z-index: 99;
    width: 300px;
    background: var(--cc-white);
    border: 1px solid var(--cc-black);
    box-shadow: 0 8px 24px rgba(0,0,0,0.12);
    padding: 18px 0;
    opacity: 0;
    transform: translateY(-8px);
    pointer-events: none;
    transition: opacity 0.18s ease, transform 0.18s ease;
  }
  .toc-overlay.open {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
  }
  .toc-overlay-label {
    font-family: var(--font-display);
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--cc-orange);
    padding: 0 20px 12px;
    border-bottom: 1px solid var(--cc-warm-gray);
  }
  ol.toc-overlay-list {
    counter-reset: toc-overlay;
    list-style: none;
    margin: 8px 0 0;
    padding: 0;
  }
  ol.toc-overlay-list li {
    counter-increment: toc-overlay;
    padding: 0;
  }
  ol.toc-overlay-list a {
    display: grid;
    grid-template-columns: 32px 1fr;
    align-items: baseline;
    gap: 8px;
    padding: 8px 20px;
    font-family: var(--font-display);
    font-size: 13px;
    color: var(--cc-black);
    text-decoration: none;
    transition: background 0.12s ease;
    line-height: 1.35;
  }
  ol.toc-overlay-list a::before {
    content: counter(toc-overlay, decimal-leading-zero);
    font-size: 10px;
    font-weight: 500;
    letter-spacing: 0.18em;
    color: var(--cc-orange);
  }
  ol.toc-overlay-list a:hover { background: var(--cc-light-gray); color: var(--cc-orange); }

  @media (max-width: 700px) {
    ol.page-toc { grid-template-columns: 1fr 1fr; }
    .toc-hamburger { top: 16px; right: 16px; }
    .toc-overlay { top: 68px; right: 16px; width: calc(100vw - 32px); max-width: 320px; }
  }

  /* ============================================
     VOICES PARTICIPANTS GRID
     ============================================ */
  .participants-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 12px;
    margin: 24px 0 36px;
  }
  .participant-card {
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    padding: 16px 18px;
    border-left: 3px solid var(--cc-orange);
    transition: border-color 0.15s ease;
  }
  .participant-card.pending { border-left-color: var(--cc-warm-gray); background: var(--cc-light-gray); }
  .participant-name {
    font-family: var(--font-display);
    font-size: 15.5px;
    font-weight: 600;
    color: var(--cc-black);
    margin-bottom: 3px;
    line-height: 1.25;
  }
  .participant-title {
    font-family: var(--font-body);
    font-size: 13px;
    color: var(--cc-ink-soft);
    line-height: 1.4;
    margin-bottom: 8px;
  }
  .participant-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    align-items: center;
  }
  .participant-tenure {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    font-weight: 600;
    padding: 3px 8px;
    background: var(--cc-light-gray);
    color: var(--cc-black);
  }
  .participant-session {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    font-weight: 600;
    padding: 3px 8px;
    background: var(--cc-orange);
    color: var(--cc-black);
  }
  .participant-card.pending .participant-session {
    background: transparent;
    color: var(--cc-ink-soft);
    border: 1px dashed var(--cc-mid-gray);
  }

  /* ============================================
     WIREFRAMES — black-and-white low/medium fidelity
     ============================================ */
  :root {
    --wf-paper: #FFFFFF;
    --wf-ink: #000000;
    --wf-soft: #F0F0F0;
    --wf-line: #BDBDBD;
    --wf-mid: #4A4A4A;
    --wf-faint: #E8E8E8;
  }

  /* Direction card wrapper */
  .wf-direction {
    margin: 36px 0 56px;
    border-top: 1px solid var(--cc-warm-gray);
    padding-top: 32px;
  }
  .wf-direction-meta {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 600;
    margin-bottom: 6px;
  }
  .wf-direction h2 {
    margin: 0 0 8px;
    letter-spacing: -0.01em;
  }
  .wf-direction-tag {
    display: inline-block;
    font-family: var(--font-display);
    font-size: 11px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--cc-black);
    border: 1px solid var(--cc-black);
    padding: 4px 10px;
    margin-left: 10px;
    vertical-align: middle;
  }
  .wf-philosophy {
    font-family: var(--font-body);
    font-size: 16px;
    line-height: 1.55;
    color: var(--cc-ink-soft);
    max-width: 820px;
    margin: 8px 0 24px;
  }
  .wf-philosophy strong { color: var(--cc-black); }

  /* Voices-vs-best-practice signposts */
  .wf-leans {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin: 16px 0 32px;
    padding: 18px 22px;
    background: var(--cc-light-gray);
    border-left: 3px solid var(--cc-black);
  }
  .wf-leans-col h4 {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--cc-orange);
    margin: 0 0 10px;
    font-weight: 600;
  }
  .wf-leans-col ul {
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .wf-leans-col li {
    font-family: var(--font-body);
    font-size: 13.5px;
    line-height: 1.55;
    padding: 4px 0;
    color: var(--cc-black);
  }
  .wf-leans-col li::before {
    content: '·  ';
    color: var(--cc-orange);
    font-weight: 600;
    margin-right: 2px;
  }

  /* Wire canvas — the BW page rendering */
  .wf-canvas {
    background: var(--wf-paper);
    border: 1px solid var(--wf-ink);
    padding: 28px;
    position: relative;
    overflow: visible;
    font-family: var(--font-body);
    margin: 24px 0;
  }
  .wf-canvas-narrow { max-width: 660px; margin: 24px auto; }
  .wf-canvas-wide { width: 100%; }

  .wf-canvas .wb {
    background: var(--wf-soft);
    border: 1px solid var(--wf-line);
    margin-bottom: 14px;
    padding: 14px 16px;
    font-family: var(--font-display);
    font-size: 11px;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--wf-ink);
    font-weight: 500;
    position: relative;
  }
  .wf-canvas .wb-tag {
    position: absolute;
    top: -8px;
    left: 12px;
    background: var(--wf-paper);
    border: 1px solid var(--wf-ink);
    padding: 2px 7px;
    font-size: 9px;
    letter-spacing: 0.16em;
    color: var(--wf-mid);
    font-weight: 500;
  }
  .wf-canvas .wb-strong {
    background: var(--wf-ink);
    color: var(--wf-paper);
  }
  .wf-canvas .wb-empty {
    background: var(--wf-paper);
    border: 1px dashed var(--wf-line);
    color: var(--wf-mid);
    font-style: italic;
    text-transform: none;
    letter-spacing: 0.02em;
    font-family: var(--font-body);
  }
  .wf-canvas .wb-row {
    display: grid;
    gap: 14px;
    margin-bottom: 14px;
  }
  .wf-canvas .wb-row > .wb { margin-bottom: 0; }
  .wf-canvas .wb-row-2 { grid-template-columns: 1fr 1fr; }
  .wf-canvas .wb-row-3 { grid-template-columns: 1fr 1fr 1fr; }
  .wf-canvas .wb-row-hero { grid-template-columns: 180px 1fr; }
  .wf-canvas .wb-row-dash { grid-template-columns: 1fr 280px; }

  .wf-canvas .wb-portrait {
    background: var(--wf-soft);
    border: 1px solid var(--wf-line);
    aspect-ratio: 1;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--wf-mid);
    overflow: hidden;
  }
  .wf-canvas .wb-portrait::before,
  .wf-canvas .wb-portrait::after {
    content: '';
    position: absolute;
    background: var(--wf-line);
    width: 141%;
    height: 1px;
    top: 50%;
    left: -20%;
  }
  .wf-canvas .wb-portrait::before { transform: rotate(45deg); }
  .wf-canvas .wb-portrait::after { transform: rotate(-45deg); }
  .wf-canvas .wb-portrait span {
    position: relative;
    background: var(--wf-paper);
    padding: 2px 6px;
    z-index: 1;
  }

  .wf-canvas .wb-title {
    font-family: var(--font-display);
    font-size: 22px;
    font-weight: 600;
    color: var(--wf-ink);
    letter-spacing: -0.01em;
    text-transform: none;
    margin-bottom: 4px;
    line-height: 1.1;
  }
  .wf-canvas .wb-sub {
    font-family: var(--font-body);
    font-size: 12px;
    color: var(--wf-mid);
    text-transform: none;
    letter-spacing: 0;
    line-height: 1.4;
  }
  .wf-canvas .wb-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    margin-top: 10px;
  }
  .wf-canvas .wb-stat {
    background: var(--wf-paper);
    border: 1px solid var(--wf-line);
    padding: 8px 10px;
    font-family: var(--font-display);
  }
  .wf-canvas .wb-stat-num {
    font-size: 18px;
    font-weight: 700;
    color: var(--wf-ink);
    letter-spacing: -0.02em;
    text-transform: none;
  }
  .wf-canvas .wb-stat-label {
    font-size: 9px;
    letter-spacing: 0.18em;
    color: var(--wf-mid);
    margin-top: 2px;
    text-transform: uppercase;
  }

  .wf-canvas .wb-textlines {
    display: flex;
    flex-direction: column;
    gap: 5px;
    text-transform: none;
    letter-spacing: 0;
  }
  .wf-canvas .wb-textlines span {
    background: var(--wf-line);
    height: 6px;
    border-radius: 1px;
  }
  .wf-canvas .wb-textlines span.s { width: 64%; }
  .wf-canvas .wb-textlines span.m { width: 86%; }
  .wf-canvas .wb-textlines span.x { width: 36%; }
  .wf-canvas .wb-textlines.wb-tight span { height: 4px; background: var(--wf-line); }

  .wf-canvas .wb-paragraph {
    text-transform: none;
    letter-spacing: 0;
    font-family: var(--font-body);
    font-size: 12.5px;
    line-height: 1.6;
    color: var(--wf-mid);
  }
  .wf-canvas .wb-paragraph + .wb-paragraph { margin-top: 10px; }

  .wf-canvas .wb-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    text-transform: none;
    letter-spacing: 0;
  }
  .wf-canvas .wb-chip {
    border: 1px solid var(--wf-ink);
    padding: 3px 9px;
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    background: var(--wf-paper);
    color: var(--wf-ink);
  }
  .wf-canvas .wb-chip.wb-chip-solid {
    background: var(--wf-ink);
    color: var(--wf-paper);
  }

  .wf-canvas .wb-logorow {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 8px;
    text-transform: none;
    letter-spacing: 0;
  }
  .wf-canvas .wb-logo {
    height: 28px;
    background: var(--wf-paper);
    border: 1px solid var(--wf-line);
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.15em;
    color: var(--wf-mid);
  }

  .wf-canvas .wb-project {
    background: var(--wf-paper);
    border: 1px solid var(--wf-line);
    padding: 12px;
    text-transform: none;
    letter-spacing: 0;
    font-family: var(--font-body);
  }
  .wf-canvas .wb-project-meta {
    display: flex;
    gap: 8px;
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--wf-mid);
    margin-bottom: 6px;
  }
  .wf-canvas .wb-project-title {
    font-family: var(--font-display);
    font-size: 13px;
    font-weight: 600;
    color: var(--wf-ink);
    margin-bottom: 6px;
  }

  .wf-canvas .wb-quote {
    background: var(--wf-paper);
    border-left: 3px solid var(--wf-ink);
    padding: 10px 14px;
    font-family: var(--font-body);
    font-size: 12px;
    line-height: 1.5;
    font-style: italic;
    color: var(--wf-ink);
    text-transform: none;
    letter-spacing: 0;
  }
  .wf-canvas .wb-quote cite {
    display: block;
    margin-top: 6px;
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    font-style: normal;
    color: var(--wf-mid);
  }

  .wf-canvas .wb-form {
    background: var(--wf-paper);
    border: 1px solid var(--wf-line);
    padding: 14px;
    text-transform: none;
    letter-spacing: 0;
  }
  .wf-canvas .wb-field {
    margin-bottom: 10px;
    font-family: var(--font-body);
  }
  .wf-canvas .wb-field label {
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--wf-mid);
    display: block;
    margin-bottom: 4px;
  }
  .wf-canvas .wb-field-input {
    height: 28px;
    background: var(--wf-soft);
    border: 1px solid var(--wf-line);
  }
  .wf-canvas .wb-btn {
    background: var(--wf-ink);
    color: var(--wf-paper);
    padding: 8px 14px;
    font-family: var(--font-display);
    font-size: 11px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    font-weight: 600;
    display: inline-block;
  }
  .wf-canvas .wb-btn-secondary {
    background: var(--wf-paper);
    color: var(--wf-ink);
    border: 1px solid var(--wf-ink);
  }
  .wf-canvas .wb-btn-row {
    display: flex;
    gap: 8px;
    text-transform: none;
    letter-spacing: 0;
  }

  .wf-canvas .wb-status-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: var(--wf-ink);
    color: var(--wf-paper);
    padding: 10px 16px;
    margin: -28px -28px 14px;
    font-family: var(--font-display);
    font-size: 11px;
    letter-spacing: 0.15em;
    font-weight: 500;
  }
  .wf-canvas .wb-status-dot {
    display: inline-block;
    width: 8px;
    height: 8px;
    background: var(--wf-paper);
    border-radius: 50%;
    margin-right: 8px;
    vertical-align: middle;
  }

  .wf-canvas .wb-tabs {
    display: flex;
    gap: 16px;
    border-bottom: 1px solid var(--wf-line);
    margin-bottom: 10px;
    text-transform: none;
    letter-spacing: 0;
  }
  .wf-canvas .wb-tab {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--wf-mid);
    padding: 4px 0;
    border-bottom: 2px solid transparent;
  }
  .wf-canvas .wb-tab.active {
    color: var(--wf-ink);
    border-bottom-color: var(--wf-ink);
    font-weight: 600;
  }

  .wf-canvas .wb-sidebar {
    background: var(--wf-paper);
    border: 1px solid var(--wf-ink);
    padding: 12px;
    height: 100%;
  }
  .wf-canvas .wb-sidebar-title {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--wf-ink);
    margin-bottom: 8px;
    padding-bottom: 6px;
    border-bottom: 1px solid var(--wf-line);
    font-weight: 600;
  }
  .wf-canvas .wb-sidebar-item {
    font-family: var(--font-body);
    font-size: 12px;
    color: var(--wf-mid);
    padding: 5px 0;
    border-bottom: 1px solid var(--wf-faint);
    text-transform: none;
    letter-spacing: 0;
    display: flex;
    justify-content: space-between;
  }
  .wf-canvas .wb-sidebar-item:last-child { border-bottom: none; }
  .wf-canvas .wb-sidebar-item .ms { font-size: 9px; color: var(--wf-mid); letter-spacing: 0.1em; text-transform: uppercase; }

  /* Annotation dots floating on wires */
  .wf-canvas .wf-dot {
    position: absolute;
    width: 22px;
    height: 22px;
    background: var(--cc-orange);
    color: var(--cc-black);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-display);
    font-size: 11px;
    font-weight: 700;
    border: 2px solid var(--cc-black);
    z-index: 2;
  }

  /* Annotation list (post-wire) */
  .wf-annotations {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 14px;
    margin: 20px 0 36px;
  }
  .wf-anno-item {
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    padding: 14px 16px;
    display: grid;
    grid-template-columns: 32px 1fr;
    gap: 12px;
    align-items: baseline;
  }
  .wf-anno-item .wf-anno-num-circle {
    width: 26px;
    height: 26px;
    background: var(--cc-orange);
    color: var(--cc-black);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-display);
    font-size: 11px;
    font-weight: 700;
  }
  .wf-anno-item h4 {
    font-family: var(--font-display);
    font-size: 12.5px;
    font-weight: 600;
    margin: 0 0 4px;
    color: var(--cc-black);
    letter-spacing: 0.02em;
  }
  .wf-anno-item p {
    margin: 0;
    font-size: 13px;
    line-height: 1.5;
    color: var(--cc-ink-soft);
  }

  /* Best-for / sacrifices summary */
  .wf-tradeoff {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin: 14px 0 24px;
  }
  .wf-tradeoff-col {
    padding: 14px 18px;
    border-left: 3px solid var(--cc-black);
    background: var(--cc-cream);
  }
  .wf-tradeoff-col.sacrifices {
    border-left-color: var(--cc-mid-gray);
    background: var(--cc-light-gray);
  }
  .wf-tradeoff-col h4 {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--cc-black);
    margin: 0 0 6px;
    font-weight: 600;
  }
  .wf-tradeoff-col p {
    margin: 0;
    font-size: 13.5px;
    line-height: 1.55;
    color: var(--cc-ink-soft);
  }

  /* Comparison summary table at the end */
  .wf-compare-table {
    width: 100%;
    border-collapse: collapse;
    font-family: var(--font-body);
    font-size: 13px;
    margin: 16px 0 28px;
  }
  .wf-compare-table th {
    text-align: left;
    padding: 12px 14px;
    background: var(--cc-black);
    color: var(--cc-white);
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    font-weight: 500;
  }
  .wf-compare-table td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--cc-warm-gray);
    vertical-align: top;
  }
  .wf-compare-table tr:nth-child(even) td { background: var(--cc-light-gray); }
  .wf-compare-table .row-label { font-weight: 600; font-family: var(--font-display); }

  /* ============================================
     ARCHETYPES + MODULE LIBRARY + ASSEMBLED KITS
     ============================================ */
  .archetype-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 14px;
    margin: 24px 0 36px;
  }
  .archetype-card {
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    border-top: 3px solid var(--cc-orange);
    padding: 20px 22px;
  }
  .archetype-card-label {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 600;
    margin-bottom: 4px;
  }
  .archetype-card h3 {
    font-family: var(--font-display);
    font-size: 19px;
    font-weight: 600;
    margin: 0 0 10px;
    letter-spacing: -0.005em;
    color: var(--cc-black);
  }
  .archetype-card .arch-desc {
    font-family: var(--font-body);
    font-size: 13.5px;
    line-height: 1.55;
    color: var(--cc-ink-soft);
    margin-bottom: 14px;
  }
  .archetype-card dl.arch-meta {
    margin: 0;
    display: grid;
    grid-template-columns: 90px 1fr;
    gap: 4px 10px;
    font-family: var(--font-body);
    font-size: 12px;
    line-height: 1.4;
  }
  .archetype-card dl.arch-meta dt {
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--cc-ink-soft);
    font-weight: 600;
    padding-top: 2px;
  }
  .archetype-card dl.arch-meta dd {
    margin: 0;
    color: var(--cc-black);
  }
  .archetype-card .arch-committee {
    font-family: var(--font-body);
    font-size: 11.5px;
    color: var(--cc-ink-soft);
    margin-top: 14px;
    padding-top: 12px;
    border-top: 1px solid var(--cc-warm-gray);
    font-style: italic;
  }
  .archetype-card .arch-committee strong { font-style: normal; color: var(--cc-black); }

  /* Module library */
  .module-cat {
    margin: 28px 0 14px;
  }
  .module-cat-label {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 600;
    margin-bottom: 10px;
  }
  .module-library {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 12px;
  }
  .module-card {
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    padding: 14px 16px;
  }
  .module-card-name {
    font-family: var(--font-display);
    font-size: 14px;
    font-weight: 600;
    color: var(--cc-black);
    margin-bottom: 4px;
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 8px;
  }
  .module-required {
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.15em;
    color: var(--cc-orange);
    font-weight: 600;
    text-transform: uppercase;
  }
  .module-optional {
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.15em;
    color: var(--cc-mid-gray);
    font-weight: 600;
    text-transform: uppercase;
  }
  .module-card-desc {
    font-family: var(--font-body);
    font-size: 12.5px;
    line-height: 1.5;
    color: var(--cc-ink-soft);
    margin-bottom: 10px;
  }
  .module-variants {
    margin-bottom: 10px;
  }
  .module-variants-label {
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--cc-ink-soft);
    margin-bottom: 4px;
    font-weight: 600;
  }
  .module-variants ul {
    margin: 0;
    padding-left: 14px;
    font-family: var(--font-body);
    font-size: 12px;
    line-height: 1.5;
    color: var(--cc-black);
  }
  .module-best-for {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
    padding-top: 10px;
    border-top: 1px solid var(--cc-warm-gray);
  }
  .best-for-tag {
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    padding: 3px 7px;
    background: var(--cc-light-gray);
    color: var(--cc-black);
    font-weight: 500;
    border: 1px solid var(--cc-warm-gray);
  }
  .best-for-tag.all { background: var(--cc-orange); border-color: var(--cc-orange); }

  /* Kit example — assembled profile per archetype */
  .kit-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 16px;
    margin: 24px 0 36px;
  }
  .kit-column {
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    padding: 18px;
  }
  .kit-column-header {
    padding-bottom: 12px;
    margin-bottom: 12px;
    border-bottom: 2px solid var(--cc-black);
  }
  .kit-column-header h3 {
    font-family: var(--font-display);
    font-size: 17px;
    font-weight: 600;
    margin: 0;
    color: var(--cc-black);
    letter-spacing: -0.005em;
  }
  .kit-column-header .kit-sub {
    font-family: var(--font-body);
    font-size: 12.5px;
    color: var(--cc-ink-soft);
    margin-top: 4px;
  }
  .kit-stack {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .kit-block {
    background: var(--cc-light-gray);
    border: 1px solid var(--cc-warm-gray);
    padding: 10px 12px;
    font-family: var(--font-body);
  }
  .kit-block.signature {
    background: var(--cc-cream-deep);
    border-color: var(--cc-orange);
    border-left: 3px solid var(--cc-orange);
  }
  .kit-block.optional {
    background: var(--cc-white);
    border-style: dashed;
    border-color: var(--cc-mid-gray);
  }
  .kit-block-name {
    font-family: var(--font-display);
    font-size: 12px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--cc-black);
    font-weight: 600;
    margin-bottom: 3px;
  }
  .kit-block.signature .kit-block-name { color: var(--cc-orange); }
  .kit-block-detail {
    font-family: var(--font-body);
    font-size: 11.5px;
    line-height: 1.4;
    color: var(--cc-ink-soft);
  }
  .kit-block.optional .kit-block-name { color: var(--cc-mid-gray); }
  .kit-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    margin: 8px 0 20px;
    font-family: var(--font-body);
    font-size: 12px;
    color: var(--cc-ink-soft);
    padding: 12px 16px;
    background: var(--cc-light-gray);
    border-left: 3px solid var(--cc-black);
  }
  .kit-legend-item {
    display: flex;
    align-items: center;
    gap: 6px;
  }
  .kit-legend-swatch {
    width: 14px;
    height: 14px;
    border: 1px solid var(--cc-warm-gray);
    background: var(--cc-light-gray);
    flex-shrink: 0;
  }
  .kit-legend-swatch.signature {
    background: var(--cc-cream-deep);
    border-color: var(--cc-orange);
    border-left: 3px solid var(--cc-orange);
  }
  .kit-legend-swatch.optional {
    background: var(--cc-white);
    border-style: dashed;
    border-color: var(--cc-mid-gray);
  }

  /* ============================================
     MODULE WIREFRAMES — compact per-module renderings
     ============================================ */
  .mod-wire-section {
    margin: 28px 0 36px;
  }
  .mod-wire-section .mod-wire-group-label {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 600;
    margin: 28px 0 12px;
    padding-bottom: 6px;
    border-bottom: 1px solid var(--cc-warm-gray);
  }
  .mod-wire-grid {
    display: flex;
    flex-direction: column;
    gap: 18px;
    margin-bottom: 24px;
  }
  .mod-wire {
    background: var(--cc-light-gray);
    border: 1px solid var(--cc-warm-gray);
    padding: 18px;
  }
  .mod-wire.mod-wire-wide {
    grid-column: 1 / -1;
  }
  .mod-wire-title {
    font-family: var(--font-display);
    font-size: 13.5px;
    font-weight: 600;
    color: var(--cc-black);
    margin-bottom: 4px;
  }
  .mod-wire-purpose {
    font-family: var(--font-body);
    font-size: 12px;
    color: var(--cc-ink-soft);
    line-height: 1.4;
    margin-bottom: 14px;
  }
  .mod-wire-variants {
    display: flex;
    flex-direction: column;
    gap: 14px;
  }
  .mod-wire-variants.v2,
  .mod-wire-variants.v3,
  .mod-wire-variants.v4 {
    flex-direction: column;
  }

  .mod-wire-variant-label {
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--cc-ink-soft);
    margin-bottom: 6px;
    font-weight: 600;
  }
  .mod-wire-note {
    font-family: var(--font-body);
    font-size: 11px;
    color: var(--cc-ink-soft);
    font-style: italic;
    margin-top: 8px;
    line-height: 1.4;
  }
  /* Smaller wire canvas for modules */
  .mod-wire .wf-canvas {
    padding: 14px;
    margin: 0;
  }
  .mod-wire .wf-canvas .wb {
    padding: 10px 12px;
    margin-bottom: 8px;
    font-size: 9.5px;
  }
  .mod-wire .wf-canvas .wb-tag {
    font-size: 8px;
  }
  .mod-wire .wf-canvas .wb-portrait { font-size: 8px; }
  .mod-wire .wf-canvas .wb-title { font-size: 16px; }
  .mod-wire .wf-canvas .wb-sub { font-size: 10px; }
  .mod-wire .wf-canvas .wb-stat-num { font-size: 14px; }
  .mod-wire .wf-canvas .wb-stat-label { font-size: 8px; }
  .mod-wire .wf-canvas .wb-chip { font-size: 8.5px; padding: 2px 6px; }
  .mod-wire .wf-canvas .wb-quote { font-size: 10px; padding: 8px 10px; }
  .mod-wire .wf-canvas .wb-quote cite { font-size: 8px; }
  .mod-wire .wf-canvas .wb-project { padding: 9px; }
  .mod-wire .wf-canvas .wb-project-meta { font-size: 8px; }
  .mod-wire .wf-canvas .wb-project-title { font-size: 11px; }
  .mod-wire .wf-canvas .wb-paragraph { font-size: 10px; line-height: 1.5; }
  .mod-wire .wf-canvas .wb-textlines span { height: 5px; }
  .mod-wire .wf-canvas .wb-textlines span.s { width: 64%; }
  .mod-wire .wf-canvas .wb-textlines span.m { width: 86%; }
  .mod-wire .wf-canvas .wb-textlines span.x { width: 36%; }
  .mod-wire .wf-canvas .wb-status-bar {
    font-size: 8.5px;
    padding: 8px 12px;
    margin: -14px -14px 10px;
  }
  .mod-wire .wf-canvas .wb-status-bar span:last-child { font-size: 8px; }
  .mod-wire .wf-canvas .wb-btn { font-size: 9px; padding: 6px 10px; }
  .mod-wire .wf-canvas .wb-field label { font-size: 8px; }
  .mod-wire .wf-canvas .wb-field-input { height: 20px; }
  .mod-wire .wf-canvas .wb-tabs { font-size: 8px; }
  .mod-wire .wf-canvas .wb-tab { font-size: 8.5px; }
  .mod-wire .wf-canvas .wb-logo { height: 22px; font-size: 8px; }
  .mod-wire .wf-canvas .wb-logorow {
    grid-template-columns: repeat(4, 1fr);
    gap: 5px;
  }

  /* Timeline-specific */
  .mod-wire .wb-timeline {
    border-left: 2px solid var(--wf-ink);
    padding-left: 14px;
    margin-left: 4px;
  }
  .mod-wire .wb-timeline-item {
    position: relative;
    padding: 8px 0 10px;
    border-bottom: 1px solid var(--wf-faint);
  }
  .mod-wire .wb-timeline-item:last-child { border-bottom: none; }
  .mod-wire .wb-timeline-item::before {
    content: '';
    position: absolute;
    left: -19px;
    top: 12px;
    width: 8px;
    height: 8px;
    background: var(--wf-ink);
    border-radius: 50%;
  }
  .mod-wire .wb-timeline-date {
    font-family: var(--font-display);
    font-size: 8px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--wf-mid);
  }
  .mod-wire .wb-timeline-title {
    font-family: var(--font-display);
    font-size: 11px;
    font-weight: 600;
    color: var(--wf-ink);
    margin: 2px 0;
  }
  .mod-wire .wb-timeline-detail {
    font-family: var(--font-body);
    font-size: 9.5px;
    color: var(--wf-mid);
    line-height: 1.4;
  }

  /* ============================================
     LIVE COMP CARDS — link out to standalone designs
     ============================================ */
  .comp-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 18px;
    margin: 24px 0 36px;
  }
  .comp-card {
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    text-decoration: none;
    color: inherit;
    display: block;
    transition: transform 0.15s, border-color 0.15s;
    overflow: hidden;
  }
  .comp-card:hover { transform: translateY(-3px); border-color: var(--cc-orange); }
  .comp-card-preview {
    aspect-ratio: 16 / 9;
    background: var(--cc-light-gray);
    position: relative;
    overflow: hidden;
  }
  .comp-card-preview.accent-cyan { background: linear-gradient(135deg, #88E8F0 0%, #5BCAD4 100%); }
  .comp-card-preview.accent-orange { background: linear-gradient(135deg, #EA633F 0%, #C24E2E 100%); }
  .comp-card-preview.accent-yellow { background: linear-gradient(135deg, #E8EB74 0%, #C4C73A 100%); }
  .comp-card-preview-label {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: var(--cc-black);
    font-family: var(--font-display);
    gap: 6px;
  }
  .comp-card-preview-name {
    font-size: 28px;
    font-weight: 600;
    letter-spacing: -0.015em;
  }
  .comp-card-preview-role {
    font-size: 10px;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    font-weight: 600;
    opacity: 0.65;
  }
  .comp-card-body { padding: 20px 22px; }
  .comp-card-tag {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 600;
    margin-bottom: 6px;
  }
  .comp-card-title {
    font-family: var(--font-display);
    font-size: 17px;
    font-weight: 600;
    color: var(--cc-black);
    margin: 0 0 8px;
    letter-spacing: -0.005em;
  }
  .comp-card-desc {
    font-family: var(--font-body);
    font-size: 13px;
    line-height: 1.55;
    color: var(--cc-ink-soft);
    margin: 0;
  }
  .comp-card-arrow {
    font-family: var(--font-display);
    font-size: 11px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 600;
    margin-top: 14px;
    display: inline-block;
  }

  /* ============================================
     PATTERNS DATA VIZ — voices page
     ============================================ */
  .patterns-section { margin: 32px 0 56px; }
  .patterns-section .patterns-intro {
    font-family: var(--font-body);
    font-size: 15.5px;
    line-height: 1.55;
    color: var(--cc-ink-soft);
    max-width: 760px;
    margin: 0 0 32px;
  }
  .patterns-subhead {
    font-family: var(--font-display);
    font-size: 11px;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 600;
    margin: 40px 0 16px;
  }

  /* Six directional theme cards */
  .theme-cards-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 14px;
    margin: 24px 0 36px;
  }
  .theme-card-direct {
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    border-top: 4px solid var(--cc-orange);
    padding: 22px 24px;
    position: relative;
  }
  .theme-card-direct .tc-num {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.22em;
    color: var(--cc-orange);
    font-weight: 700;
    margin-bottom: 6px;
  }
  .theme-card-direct .tc-stat {
    position: absolute;
    top: 18px; right: 22px;
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--cc-ink-soft);
    background: var(--cc-light-gray);
    padding: 3px 8px;
    font-weight: 600;
  }
  .theme-card-direct h4 {
    font-family: var(--font-display);
    font-size: 19px;
    line-height: 1.2;
    font-weight: 500;
    color: var(--cc-black);
    margin: 0 0 12px;
    letter-spacing: -0.005em;
    max-width: 86%;
  }
  .theme-card-direct p {
    font-family: var(--font-body);
    font-size: 13.5px;
    line-height: 1.55;
    color: var(--cc-ink-soft);
    margin: 0;
  }

  /* Theme strength horizontal bar chart */
  .theme-strength { display: grid; gap: 10px; margin: 16px 0 32px; }
  .theme-bar {
    display: grid;
    grid-template-columns: 240px 1fr 60px;
    gap: 14px;
    align-items: center;
    font-family: var(--font-body);
  }
  .theme-bar-label {
    font-size: 13px;
    color: var(--cc-black);
    font-weight: 500;
  }
  .theme-bar-track {
    height: 14px;
    background: var(--cc-light-gray);
    border: 1px solid var(--cc-warm-gray);
    position: relative;
  }
  .theme-bar-fill {
    height: 100%;
    background: var(--cc-orange);
    transition: width 0.3s ease;
  }
  .theme-bar-fill.partial { background: var(--cc-cream-deep); }
  .theme-bar-count {
    font-family: var(--font-display);
    font-size: 12px;
    color: var(--cc-orange);
    font-weight: 700;
    letter-spacing: 0.06em;
    text-align: right;
  }

  /* Lead routing distribution segmented bar */
  .routing-distribution {
    margin: 16px 0 28px;
  }
  .routing-bar {
    display: flex;
    height: 56px;
    border: 1px solid var(--cc-black);
    overflow: hidden;
  }
  .routing-segment {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 6px 12px;
    text-align: center;
    border-right: 1px solid rgba(18,18,18,0.15);
  }
  .routing-segment:last-child { border-right: none; }
  .routing-segment .rs-count {
    font-family: var(--font-display);
    font-size: 22px;
    font-weight: 500;
    line-height: 1;
    color: var(--cc-black);
    letter-spacing: -0.02em;
  }
  .routing-segment .rs-label {
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--cc-black);
    margin-top: 4px;
    font-weight: 600;
  }
  .routing-segment.tier-1 { background: var(--cc-orange); }
  .routing-segment.tier-2 { background: #F08F73; }
  .routing-segment.tier-3 { background: var(--cc-cream-deep); }
  .routing-segment.tier-4 { background: var(--cc-warm-gray); }
  .routing-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    margin-top: 12px;
    font-family: var(--font-body);
    font-size: 12px;
    color: var(--cc-ink-soft);
  }
  .routing-legend strong { color: var(--cc-black); font-family: var(--font-display); }

  /* Discovery curve — sessions */
  .discovery-curve {
    display: grid;
    gap: 8px;
    margin: 16px 0 32px;
    max-width: 640px;
  }
  .discovery-row {
    display: grid;
    grid-template-columns: 100px 1fr 80px;
    gap: 14px;
    align-items: center;
    font-family: var(--font-body);
  }
  .discovery-label {
    font-family: var(--font-display);
    font-size: 11px;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--cc-black);
    font-weight: 600;
  }
  .discovery-track {
    height: 22px;
    background: var(--cc-light-gray);
    border: 1px solid var(--cc-warm-gray);
    position: relative;
    display: flex;
    align-items: center;
  }
  .discovery-fill {
    height: 100%;
    background: var(--cc-orange);
    display: flex;
    align-items: center;
    padding-left: 10px;
    font-family: var(--font-display);
    font-size: 11px;
    font-weight: 600;
    color: var(--cc-black);
    letter-spacing: 0.05em;
  }
  .discovery-cumulative {
    font-family: var(--font-display);
    font-size: 11px;
    color: var(--cc-ink-soft);
    font-weight: 500;
    letter-spacing: 0.05em;
  }

  /* Theme × Voice matrix */
  .voice-matrix {
    margin: 16px 0 32px;
    overflow-x: auto;
  }
  .voice-matrix-table {
    width: 100%;
    border-collapse: collapse;
    font-family: var(--font-body);
    font-size: 12px;
    min-width: 720px;
  }
  .voice-matrix-table th, .voice-matrix-table td {
    padding: 10px 8px;
    text-align: center;
    vertical-align: middle;
  }
  .voice-matrix-table th {
    font-family: var(--font-display);
    font-size: 9.5px;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--cc-ink-soft);
    font-weight: 600;
    border-bottom: 1px solid var(--cc-warm-gray);
    background: var(--cc-light-gray);
  }
  .voice-matrix-table th.voice-th {
    text-align: left;
    padding-left: 14px;
    width: 160px;
  }
  .voice-matrix-table td.voice-name {
    font-family: var(--font-display);
    font-size: 12.5px;
    text-align: left;
    padding-left: 14px;
    color: var(--cc-black);
    font-weight: 500;
    background: var(--cc-light-gray);
  }
  .voice-matrix-table td {
    border-bottom: 1px solid var(--cc-warm-gray);
  }
  .voice-matrix-table tr:last-child td { border-bottom: none; }
  /* Dot indicators for emphasis level */
  .em-dot {
    display: inline-block;
    width: 14px; height: 14px;
    border-radius: 50%;
    background: var(--cc-orange);
  }
  .em-strong { background: var(--cc-orange); }
  .em-med { background: var(--cc-orange); opacity: 0.5; }
  .em-light { background: var(--cc-warm-gray); width: 8px; height: 8px; }
  .em-none { background: transparent; border: 1px dashed var(--cc-warm-gray); width: 8px; height: 8px; }
  /* For routing tier — small text label */
  .em-tier {
    font-family: var(--font-display);
    font-size: 9px;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    padding: 3px 7px;
    font-weight: 600;
    border-radius: 2px;
  }
  .em-tier.t1 { background: var(--cc-orange); color: var(--cc-black); }
  .em-tier.t2 { background: #F08F73; color: var(--cc-black); }
  .em-tier.t3 { background: var(--cc-cream-deep); color: var(--cc-black); }
  .em-tier.t4 { background: var(--cc-warm-gray); color: var(--cc-black); }

  .matrix-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 18px;
    margin-top: 14px;
    font-family: var(--font-body);
    font-size: 12px;
    color: var(--cc-ink-soft);
  }
  .matrix-legend-item {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  @media (max-width: 760px) {
    .theme-bar { grid-template-columns: 1fr; gap: 4px; }
    .theme-bar-track { order: 2; }
    .theme-bar-count { text-align: left; order: 3; }
    .routing-segment .rs-count { font-size: 18px; }
    .routing-segment .rs-label { font-size: 8px; }
    .discovery-row { grid-template-columns: 80px 1fr 60px; gap: 8px; }
  }

  /* ============================================
     EXPLORATIONS — design direction thumbnails
     ============================================ */
  .expl-direction {
    margin: 36px 0 28px;
    padding: 28px 0;
    border-top: 1px solid var(--cc-warm-gray);
  }
  .expl-direction:first-of-type { border-top: none; padding-top: 8px; }
  .expl-direction-head {
    display: grid;
    grid-template-columns: 130px 1fr;
    gap: 20px;
    align-items: baseline;
    margin-bottom: 22px;
  }
  .expl-direction-num {
    font-family: var(--font-display);
    font-size: 56px;
    font-weight: 400;
    line-height: 1;
    color: var(--cc-orange);
    letter-spacing: -0.04em;
  }
  .expl-direction-meta { display: flex; flex-direction: column; gap: 4px; }
  .expl-direction-archetype {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 600;
  }
  .expl-direction-name {
    font-family: var(--font-display);
    font-size: 28px;
    font-weight: 500;
    color: var(--cc-black);
    margin: 0;
    letter-spacing: -0.015em;
    line-height: 1.1;
  }
  .expl-direction-desc {
    font-family: var(--font-body);
    font-size: 14px;
    line-height: 1.55;
    color: var(--cc-ink-soft);
    margin: 4px 0 0;
    max-width: 720px;
  }
  .expl-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
  }
  .expl-card {
    background: var(--cc-white);
    border: 1px solid var(--cc-warm-gray);
    text-decoration: none;
    color: inherit;
    display: flex;
    flex-direction: column;
    transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
    overflow: hidden;
  }
  .expl-card:hover {
    transform: translateY(-3px);
    border-color: var(--cc-orange);
    box-shadow: 0 8px 20px rgba(18, 18, 18, 0.06);
  }
  .expl-card-thumb {
    aspect-ratio: 3 / 4;
    background: var(--cc-light-gray);
    overflow: hidden;
    border-bottom: 1px solid var(--cc-warm-gray);
    position: relative;
  }
  .expl-card-thumb img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: top center;
    transition: transform 0.4s ease;
  }
  .expl-card:hover .expl-card-thumb img { transform: scale(1.02); }
  .expl-card-body { padding: 14px 16px 16px; }
  .expl-card-version {
    font-family: var(--font-display);
    font-size: 9.5px;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--cc-orange);
    font-weight: 700;
    margin-bottom: 4px;
  }
  .expl-card-name {
    font-family: var(--font-display);
    font-size: 14px;
    font-weight: 500;
    color: var(--cc-black);
    margin: 0 0 4px;
    line-height: 1.25;
    letter-spacing: -0.005em;
  }
  .expl-card-note {
    font-family: var(--font-body);
    font-size: 12px;
    line-height: 1.45;
    color: var(--cc-ink-soft);
    margin: 0;
  }
  @media (max-width: 760px) {
    .expl-grid { grid-template-columns: 1fr; }
    .expl-direction-head { grid-template-columns: 1fr; gap: 8px; }
    .expl-direction-num { font-size: 40px; }
  }
